def bar_limits(values, pad=0.1):
    if not values:
        return (0.0, 1.0)
    lo, hi = min(values), max(values)
    span = hi - lo
    if span == 0:
        return (0.0, 1.0)
    return (lo - pad * span, hi + pad * span)

def bar_limits(values, pad=0.1):
    lo = min([0.0] + list(values))
    hi = max([0.0] + list(values))
    if hi == lo:
        return (0.0, 1.0)
    return (lo * (1 + pad), hi * (1 + pad))

def bar_limits(values, pad=0.1):
    lo = min([0.0] + list(values))
    hi = max([0.0] + list(values))
    span = hi - lo
    if lo < 0:
        lo = lo - pad * span
    if hi > 0:
        hi = hi + pad * span
    return (lo, hi)
